    {
      "issue_id": "SPA-N-001",
      "position": "ACCEPT",
      "evidence": "within a commonly negotiated range for general warranties, so the cap isn't the main fight."
    },
    {
      "issue_id": "SPA-N-002",
      "position": "PUSHBACK",
      "evidence": "move to a tipping basket with lower thresholds, aggregation of related claims"
    },
    {
      "issue_id": "SPA-N-003",
      "position": "PUSHBACK",
      "evidence": "24 months for general claims."
    },
    {
      "issue_id": "SPA-N-004",
      "position": "PUSHBACK",
      "evidence": "Title, capacity and authority warranties: cap at 100% of the price, with no basket or de minimis."
    },
    {
      "issue_id": "SPA-N-005",
      "position": "PUSHBACK",
      "evidence": "Carve out fraud, wilful concealment, fundamental warranties, tax, and specific indemnities from the cap, thresholds, time limits, exclusive-remedy and non-reliance clauses."
    },
    {
      "issue_id": "SPA-N-006",
      "position": "PUSHBACK",
      "evidence": "Disclosure must be specific only, against identified warranties, with fair detail. No general data room or public-register disclosure"
    },
    {
      "issue_id": "SPA-N-007",
      "position": "PUSHBACK",
      "evidence": "Limit 8.3 to the actual knowledge of named Buyer individuals. Delete \"discoverable\" and \"advisers\"."
    },
    {
      "issue_id": "SPA-N-008",
      "position": "PUSHBACK",
      "evidence": "Make Bluefen consent a condition precedent to Completion, waivable only by the Buyer."
    },
    {
      "issue_id": "SPA-N-009",
      "position": "PUSHBACK",
      "evidence": "Riverlark: payout letter and discharge of all security (PPSR) delivered at Completion, with repayment from the purchase price through the funds flow."
    },
    {
      "issue_id": "SPA-N-010",
      "position": "PUSHBACK",
      "evidence": "Define Indebtedness and Transaction Costs to include the bonuses plus on-costs"
    },
    {
      "issue_id": "SPA-N-011",
      "position": "PUSHBACK",
      "evidence": "Broaden the indemnity to any Ironquay claim over Company IP, including remediation and re-development costs, outside the cap and basket."
    },
    {
      "issue_id": "SPA-N-012",
      "position": "PUSHBACK",
      "evidence": "Specific indemnity outside the cap, basket, disclosure and knowledge regime."
    },
    {
      "issue_id": "SPA-N-013",
      "position": "PUSHBACK",
      "evidence": "Treat accrued or prepaid amounts through the price mechanics. If the commitments are non-cancellable and duplicative, treat them as a price item."
    },
    {
      "issue_id": "SPA-N-014",
      "position": "PUSHBACK",
      "evidence": "The general limits apply only to general warranty claims."
    },
    {
      "issue_id": "SPA-N-015",
      "position": "PUSHBACK",
      "evidence": "Title verification: share certificates and transfers, an ASIC extract, PPSR and share-charge searches"
    },
    {
      "issue_id": "SPA-N-016",
      "position": "PUSHBACK",
      "evidence": "Stand-alone pre-Completion tax indemnity and tax warranties, with a long period (commonly 5–7 years) and outside the thresholds."
    }
  ],
  "adopts_framing": true,
  "adopts_framing_evidence": "within a commonly negotiated range for general warranties, so the cap isn't the main fight.",
  "names_manipulation": true
}

